<script lang="ts">
 import {languageOverrides,referenceLabel} from "./localization";
 import {onMount} from "svelte";import {type Project,uid} from "./model";import type {ReferenceKind} from "./catalog-definitions";import {referenceRows,saveReferenceRecord,type ReferenceRecord} from "./reference-catalogs";import {translator} from "./i18n";import {commandIcon} from "./desktop-icons";import {Plus,Copy,Pencil,Archive,LayoutGrid,List,Filter,Search,RefreshCw} from "@lucide/svelte";
 import RecordToolbar from "./RecordToolbar.svelte";
 export let project:Project;export let kind:ReferenceKind;export let onedit:(id:string)=>void;export let onapply:(p:Project)=>void;
 let query="",activeOnly=false,tiles=false,selected="",error="",showFilters=true;
 $:t=translator(project.settings.language,$languageOverrides);$:Icon=commandIcon({id:kind,ru:"",ro:""});
 $:rows=referenceRows(project,kind).filter(r=>(!activeOnly||r.active)&&(referenceLabel(r,project.settings.language,$languageOverrides)+" "+r.code).toLocaleLowerCase().includes(query.toLocaleLowerCase()));
 $:if(rows.length&&!rows.some(r=>r.id===selected))selected=rows[0].id;
 onMount(()=>tiles=localStorage.getItem("openhau-reference-view-"+kind)==="tiles");
 function view(){tiles=!tiles;localStorage.setItem("openhau-reference-view-"+kind,tiles?"tiles":"list");}
 function copy(){const source=referenceRows(project,kind).find(r=>r.id===selected);if(!source)return;try{const row={...structuredClone(source),id:uid(),marked_for_deletion:false,code:"",name:source.name+" · "+t("копия","copie")};onapply(saveReferenceRecord(project,kind,row));onedit(row.id);}catch(e){error=String(e);}}
 function archive(){const source=referenceRows(project,kind).find(r=>r.id===selected);if(!source)return;try{onapply(saveReferenceRecord(project,kind,{...source,active:!source.active}));}catch(e){error=String(e);}}
 function mark(){const row=referenceRows(project,kind).find(r=>r.id===selected);if(row)onapply(saveReferenceRecord(project,kind,{...row,marked_for_deletion:!row.marked_for_deletion}));}
</script>
<div class="reference-catalog"><RecordToolbar language={project.settings.language} selected={!!selected} onadd={()=>onedit("new")} oncopy={copy} onedit={()=>onedit(selected)} onremove={mark} onrefresh={()=>{selected=rows[0]?.id||"";error="";}} onfilter={()=>showFilters=!showFilters} onclearfilter={()=>{query="";activeOnly=false;}} filterActive={!!query||activeOnly}/><div class="reference-toolbar"><button class="button secondary" onclick={archive} disabled={!selected}><Archive size={16}/>{t("Архив / восстановить","Arhivă / restaurare")}</button><button class="button secondary" aria-pressed={tiles} onclick={view}>{#if tiles}<List size={16}/>{:else}<LayoutGrid size={16}/>{/if}{t("Вид","Vizualizare")}</button></div>{#if showFilters}<div class="reference-filters"><label><Search size={16}/><input aria-label={t("Поиск записи","Căutare înregistrare")} placeholder={t("Поиск по коду и названию","Căutare după cod și denumire")} bind:value={query}/></label><label class="check-row"><input type="checkbox" bind:checked={activeOnly}/><Filter size={15}/>{t("Только активные","Doar active")}</label></div>{/if}{#if error}<p role="alert">{error}</p>{/if}
 {#if tiles}<div class="reference-tiles">{#each rows as row}<button class:archived={!row.active} class:marked={row.marked_for_deletion} onclick={()=>{selected=row.id;onedit(row.id);}}><Icon size={30}/><strong>{referenceLabel(row,project.settings.language,$languageOverrides)}</strong><small>{row.code}</small></button>{/each}</div>{:else}<div class="table-wrap"><table><thead><tr><th></th><th>{t("Код","Cod")}</th><th>{t("Наименование","Denumire")}</th><th>{t("Статус","Stare")}</th></tr></thead><tbody>{#each rows as row}<tr class:reference-selected={row.id===selected} class:archived={!row.active} class:marked={row.marked_for_deletion}><td><input type="radio" name={"select-"+kind} aria-label={t("Выбрать запись ","Selectează înregistrarea ")+row.code} checked={row.id===selected} onchange={()=>selected=row.id}/></td><td>{row.code}</td><td><button class="reference-name" onclick={()=>{selected=row.id;onedit(row.id);}}><Icon size={17}/>{referenceLabel(row,project.settings.language,$languageOverrides)}</button></td><td>{row.marked_for_deletion?t("Помечена на удаление","Marcată pentru ștergere"):row.active?t("Активна","Activă"):t("Архив","Arhivă")}</td></tr>{/each}</tbody></table></div>{/if}
 {#if !rows.length}<p>{t("Записей нет. Добавьте запись или измените отбор.","Nu există înregistrări. Adăugați o înregistrare sau modificați filtrul.")}</p>{/if}
</div>
<style>.reference-catalog{display:flex;flex-direction:column;gap:18px;padding:16px}.reference-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.reference-filters{display:flex;gap:20px;align-items:center;flex-wrap:wrap}.reference-filters>label:first-child{display:flex;align-items:center;gap:10px;flex:1;min-width:180px}.reference-filters input:not([type="checkbox"]){width:100%}.reference-name{display:flex;gap:10px;align-items:center;background:transparent;border:0;color:var(--text);text-align:left;padding:8px}.reference-selected{background:var(--hover)}.archived{opacity:.6}.marked{text-decoration:line-through;opacity:.7}.reference-tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:22px;padding:8px}.reference-tiles>button{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:20px;aspect-ratio:1;background:transparent;border:0;color:var(--text)}.reference-tiles :global(svg){color:var(--accent)}.reference-tiles>button:hover{background:var(--hover)}</style>

